#!/usr/bin/env node
'use strict';
// Generic, ROM-bound iterative replay for projects generated by Forja65.
// It never pretends to emulate an unknown CPU path: a failed run only adds
// observations recorded by the compiled runtime through learn-crash.
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
function flags(argv){
  const opts={};for(let i=0;i<argv.length;i++){
    if(!argv[i].startsWith('--')||i+1===argv.length||argv[i+1].startsWith('--'))throw Error('Expected --option value: '+argv[i]);
    opts[argv[i].slice(2)]=argv[++i];
  }return opts;
}
function integer(value,def,min,max,name){let x=value===undefined?def:Number(value);if(!Number.isSafeInteger(x)||x<min||x>max)throw Error('Invalid '+name);return x;}
function findGame(build){
  const names=process.platform==='win32'?['Release/game.exe','game.exe','Debug/game.exe','game']:['game','Release/game.exe','game.exe'];
  for(const name of names){const p=path.join(build,name);if(fs.existsSync(p))return p;}
  throw Error('Compiled game not found in '+build+'; run cmake --build first');
}
function frameStats(file){
  const result={frames:0,unique_framebuffers:0,unique_wram:0,last_frame:null,first_changed_frame:null};
  if(!fs.existsSync(file))return result;
  const framebuffer=new Set(),wram=new Set();let original=null;
  for(const line of fs.readFileSync(file,'utf8').split(/\r?\n/)){
    const m=line.match(/^frame=(\d+) framebuffer=([0-9a-f]+) wram=([0-9a-f]+)/i);if(!m)continue;
    const frame=Number(m[1]);result.frames++;result.last_frame=frame;framebuffer.add(m[2]);wram.add(m[3]);
    if(original===null)original=m[2];else if(result.first_changed_frame===null&&m[2]!==original)result.first_changed_frame=frame;
  }
  result.unique_framebuffers=framebuffer.size;result.unique_wram=wram.size;return result;
}
function run(exe,args,cwd,log,env,timeoutMs){
  fs.mkdirSync(path.dirname(log),{recursive:true});const fd=fs.openSync(log,'w');
  const started=process.hrtime.bigint();
  let r;try{r=cp.spawnSync(exe,args,{cwd,env:env||process.env,stdio:['ignore',fd,fd],timeout:timeoutMs});}finally{fs.closeSync(fd);}
  const elapsedMs=Number((process.hrtime.bigint()-started)/1000000n);
  return {exit_code:r.status,signal:r.signal||null,error:r.error?.message||null,log,duration_ms:elapsedMs};
}
function options(argv){
  const o=flags(argv);if(!o.project)throw Error('Usage: node tools/replay-converge.js --project PATH [--build PATH] [--input replay.trace] [--frames 1800] [--iterations 5] [--max 16384] [--capture-frame 1200]');
  const project=path.resolve(o.project),build=path.resolve(o.build||path.join(project,'build')),input=o.input?path.resolve(o.input):null;
  if(!fs.existsSync(path.join(project,'assets/cart-data.bin')))throw Error('Missing cart-data.bin in project; cannot prove ROM identity');
  if(!fs.existsSync(path.join(project,'analysis/generation-options.json')))throw Error('Missing generation-options.json');
  if(!fs.existsSync(path.join(build,'CMakeCache.txt')))throw Error('Build directory not configured: '+build);
  if(input){if(!fs.existsSync(input))throw Error('Missing replay trace: '+input);if(!/frame=\d+\s+joy1=[a-f\d]+/i.test(fs.readFileSync(input,'utf8')))throw Error('Replay has no controller events');}
  const frames=integer(o.frames,1800,1,100000,'frames'),iterations=integer(o.iterations,5,0,100,'iterations'),max=integer(o.max,16384,256,100000,'max');
  const capture=integer(o['capture-frame'],frames,1,frames,'capture-frame');
  const captureFrames=o['capture-frames']===undefined?null:o['capture-frames'].split(',').map((raw)=>{
    if(!/^[0-9]+$/.test(raw))throw Error('Invalid --capture-frames list');
    return integer(raw,1,1,frames,'capture-frames');
  });
  if(captureFrames&&(!captureFrames.length||new Set(captureFrames).size!==captureFrames.length))throw Error('Capture frames must be unique and nonempty');
  const stallIterations=integer(o['stall-iterations'],0,0,100,'stall-iterations');
  const prelearn=integer(o.prelearn,0,0,1,'prelearn');
  return {project,build,input,frames,iterations,max,capture,captureFrames,stallIterations,prelearn,timeout:integer(o.timeout,60000,1000,600000,'timeout')};
}
function blockedEdge(log){
  const match=String(log||'').match(/fluxo CFG nao resolvido em pc=(\d+) target=(\d+)/);
  if(match)return 'CFG:'+match[1]+':'+match[2];
  const state=String(log||'').match(/estado M\/X\/C nao recompilado em pc=(\d+)/);
  if(state)return 'STATE:'+state[1];
  const ret=String(log||'').match(/retorno 65C816 nao corresponde[^\r\n]*/);
  return ret?'RETURN:'+ret[0]:null;
}
function isStalled(rows,threshold){
  if(!threshold||rows.length<threshold)return false;
  const window=rows.slice(-threshold);
  if(window.some(r=>r.run.exit_code!==2||r.frames===0))return false;
  // Reaching the same frame with a different *observed* target is genuine
  // forward discovery. Prior versions stopped early while iterating dynamic
  // callbacks within one frame. A repeated edge, not the frame, is a stall.
  const key=r=>[r.frames,r.unique_framebuffers,r.unique_wram,r.first_changed_frame,r.blocked_edge||''].join(':');
  return window.every(r=>key(r)===key(window[0]));
}
// Read-only preflight: a previous failed replay may have produced a *new*
// verified runtime edge, but that edge was never fed through learn-crash.
// Replaying 2500 frames before ingesting it wastes minutes. ROM mismatch is
// fatal rather than importing cross-game evidence.
function pendingRuntimeEvidence(project,build){
  const evidenceFile=path.join(build,'forja65-runtime-hints.txt');
  if(!fs.existsSync(evidenceFile))return {exists:false,needs_build:false,unlearned:0,uncompiled:0,stale:0};
  const A=require('./dispatch-frontier-audit.js');
  const opts=JSON.parse(fs.readFileSync(path.join(project,'analysis/generation-options.json'),'utf8'));
  const learned=fs.readFileSync(path.join(project,'analysis/runtime-hints.txt'),'utf8');
  const d=A.parseDispatch(fs.readFileSync(path.join(project,'src/dispatch.cpp'),'utf8'));
  const audit=A.auditRuntimeEvidence(fs.readFileSync(evidenceFile,'utf8'),learned,d,opts.rom.toLowerCase());
  return {exists:true,needs_build:audit.unlearned>0||audit.uncompiled>0,unlearned:audit.unlearned,uncompiled:audit.uncompiled,
    stale:audit.stale_rom_hints,malformed:audit.malformed_lines.length,excluded_non_rom:audit.excluded_non_rom.length};
}
function converge(cfg){
  const report={schema:1,project:cfg.project,build:cfg.build,input_trace:cfg.input,requested_frames:cfg.frames,capture_frames:cfg.captureFrames||[cfg.capture],max_cfg:cfg.max,iterations_limit:cfg.iterations,stall_limit:cfg.stallIterations||0,prelearn_enabled:!!cfg.prelearn,iterations:[],status:'INCOMPLETE'};
  const reports=path.join(cfg.project,'reports','replay-convergence');fs.mkdirSync(reports,{recursive:true});
  const jsonPath=path.join(cfg.project,'reports','replay-convergence.json');
  const save=()=>fs.writeFileSync(jsonPath,JSON.stringify(report,null,2)+'\n');
  if(cfg.prelearn){
    const pending=pendingRuntimeEvidence(cfg.project,cfg.build);
    report.preflight=pending;save();
    if(pending.stale||pending.malformed){report.status='PREFLIGHT_INVALID_RUNTIME_EVIDENCE';save();return 2;}
    if(pending.needs_build){
      const script=path.join(__dirname,'forja65.js');
      report.preflight.learn=run(process.execPath,[script,'learn-crash',cfg.project,'--from',cfg.build,'--max',String(cfg.max)],cfg.project,path.join(reports,'preflight-learn.log'),process.env,cfg.timeout*2);
      save();
      if(report.preflight.learn.exit_code!==0){report.status='PREFLIGHT_LEARNING_BLOCKED';save();return 2;}
      report.preflight.build=run('cmake',['--build',cfg.build,'--target','game','--config','Release','-j','6'],cfg.project,path.join(reports,'preflight-build.log'),process.env,cfg.timeout*3);
      save();
      if(report.preflight.build.exit_code!==0){report.status='PREFLIGHT_BUILD_FAILED';save();return 2;}
      console.log('Preflight learned and compiled pending runtime evidence before replay.');
    }
  }
  for(let i=0;i<=cfg.iterations;i++){
    const index=String(i).padStart(2,'0'),game=findGame(cfg.build),hashPath=path.join(cfg.build,'forja65-frame-hashes.txt');
    fs.rmSync(hashPath,{force:true});
    const env={...process.env,FORJA65_HEADLESS:'1',FORJA65_UNCAPPED:'1',FORJA65_FRAME_HASHES:'1',FORJA65_HEADLESS_FRAMES:String(cfg.frames)};
    if(cfg.input)env.FORJA65_INPUT_REPLAY=cfg.input;
    if(cfg.captureFrames){env.FORJA65_CAPTURE_FRAMES=cfg.captureFrames.join(',');env.FORJA65_CAPTURE_DIR=path.join(reports,'capture-'+index);}
    else if(cfg.capture){env.FORJA65_CAPTURE_FRAME=String(cfg.capture);env.FORJA65_CAPTURE_DIR=path.join(reports,'capture-'+index);}
    const launch=run(game,[],cfg.build,path.join(reports,'run-'+index+'.log'),env,cfg.timeout);
    const stats=frameStats(hashPath);
    const lastError=fs.existsSync(launch.log)?fs.readFileSync(launch.log,'utf8').slice(-8192):'';
    const row={attempt:i,run:launch,...stats,frames_per_second:launch.duration_ms>0?Number((stats.frames*1000/launch.duration_ms).toFixed(2)):null,blocked_edge:blockedEdge(lastError)};
    report.iterations.push(row);
    save(); // A crashing compiler or interrupted run still leaves an accurate checkpoint.
    console.log('Attempt '+i+': exit='+launch.exit_code+' frames='+stats.frames+' framebuffer_variants='+stats.unique_framebuffers+' duration_ms='+launch.duration_ms+' fps='+row.frames_per_second);
    if(launch.exit_code===0){report.status=stats.last_frame!==null&&stats.last_frame+1>=cfg.frames?'FRAMES_REACHED':'EARLY_EXIT';break;}
    if(isStalled(report.iterations,cfg.stallIterations)){report.status='STALLED_UNRESOLVED_CFG';break;}
    if(i===cfg.iterations){report.status='ITERATION_LIMIT';break;}
    const reason=lastError;
    if(!/fluxo CFG nao resolvido|estado M\/X\/C nao recompilado|retorno 65C816 nao corresponde/.test(reason)){
      report.status=launch.error?'RUN_TIMEOUT_OR_ERROR':'UNSUPPORTED_FAILURE';break;
    }
    const forja=path.join(__dirname,'forja65.js');
    const learned=run(process.execPath,[forja,'learn-crash',cfg.project,'--from',cfg.build,'--max',String(cfg.max)],cfg.project,path.join(reports,'learn-'+index+'.log'),process.env,cfg.timeout*2);
    row.learn=learned;save();
    if(learned.exit_code!==0){report.status='LEARNING_BLOCKED';break;}
    const buildResult=run('cmake',['--build',cfg.build,'--target','game','--config','Release','-j','6'],cfg.project,path.join(reports,'build-'+index+'.log'),process.env,cfg.timeout*3);
    row.build=buildResult;save();
    if(buildResult.exit_code!==0){report.status='BUILD_FAILED';break;}
  }
  save();console.log('Result '+report.status+'; report '+jsonPath);
  return report.status==='FRAMES_REACHED'?0:2;
}
if(require.main===module){try{process.exitCode=converge(options(process.argv.slice(2)));}catch(e){console.error(e.message);process.exitCode=2;}}
module.exports={options,frameStats,blockedEdge,isStalled,pendingRuntimeEvidence,converge};
